use super::*;

#[test]
fn inverted_signed_window_has_one_refusal_independent_of_verifier_time() {
    let store = StdArc::new(InMemoryApprovalStore::new());
    let guard = ApprovalGuard::new(store.clone());
    let request = hitl_make_request();
    let approver = CoreKeypair::generate();
    guard
        .evaluate(
            ApprovalContext {
                request: &request,
                constraints: &[],
                policy_id: "policy-hitl",
                trusted_approvers: &[approver.public_key()],
                presented_token: None,
                force_approval: true,
                approval_id_override: Some("inverted".into()),
            },
            90,
        )
        .unwrap();
    let pending = store.get_pending("inverted").unwrap().unwrap();
    let token = ApprovalToken {
        approval_id: pending.approval_id.clone(),
        approver: approver.public_key(),
        governed_token: GovernedApprovalToken::sign(
            GovernedApprovalTokenBody {
                id: "inverted-token".into(),
                approver: approver.public_key(),
                subject: request.capability.subject.clone(),
                governed_intent_hash: pending.parameter_hash.clone(),
                request_id: pending.approval_id.clone(),
                threshold_proposal_hash: None,
                issued_at: 101,
                expires_at: 100,
                decision: GovernedApprovalDecision::Approved,
            },
            &approver,
        )
        .unwrap(),
    };
    for now in [99, 100, 101] {
        let result = token.verify_against(&pending, now);
        assert!(
            matches!(result, Err(KernelError::ApprovalRejected(ref reason)) if reason == "approval token validity window is inverted"),
            "{result:?}"
        );
    }
    assert!(!store
        .is_consumed("inverted-token", &pending.parameter_hash)
        .unwrap());
}

#[test]
fn invalid_deadlines_publish_neither_pending_request_nor_notification() {
    for (now, ttl, expected) in [
        (
            100,
            0,
            "approval request lifetime is outside the supported range",
        ),
        (
            100,
            3601,
            "approval request lifetime is outside the supported range",
        ),
        (u64::MAX, 1, "approval request expiry overflow"),
        (u64::MAX - 3599, 3600, "approval request expiry overflow"),
    ] {
        let store = StdArc::new(InMemoryApprovalStore::new());
        let recorder = StdArc::new(RecordingChannel::new());
        let guard = ApprovalGuard::new(store.clone())
            .with_channel(recorder.clone())
            .with_default_ttl(ttl);
        let request = hitl_make_request();
        let approver = CoreKeypair::generate();
        let result = guard.evaluate(
            ApprovalContext {
                request: &request,
                constraints: &[],
                policy_id: "policy-hitl",
                trusted_approvers: &[approver.public_key()],
                presented_token: None,
                force_approval: true,
                approval_id_override: Some("deadline-boundary".into()),
            },
            now,
        );
        assert!(
            matches!(result, Err(KernelError::ApprovalRejected(ref reason)) if reason == expected),
            "{result:?}"
        );
        assert!(store.get_pending("deadline-boundary").unwrap().is_none());
        assert_eq!(recorder.len(), 0);
    }
}

#[test]
fn largest_representable_approval_expiry_is_published_exactly() {
    let store = StdArc::new(InMemoryApprovalStore::new());
    let recorder = StdArc::new(RecordingChannel::new());
    let guard = ApprovalGuard::new(store.clone())
        .with_channel(recorder.clone())
        .with_default_ttl(3600);
    let request = hitl_make_request();
    let approver = CoreKeypair::generate();
    let verdict = guard
        .evaluate(
            ApprovalContext {
                request: &request,
                constraints: &[],
                policy_id: "policy-hitl",
                trusted_approvers: &[approver.public_key()],
                presented_token: None,
                force_approval: true,
                approval_id_override: Some("deadline-boundary".into()),
            },
            u64::MAX - 3600,
        )
        .unwrap();
    let HitlVerdict::Pending { request, .. } = verdict else {
        panic!("expected pending request");
    };
    assert_eq!(request.expires_at, u64::MAX);
    assert_eq!(request.created_at, u64::MAX - 3600);
    assert_eq!(
        store
            .get_pending("deadline-boundary")
            .unwrap()
            .unwrap()
            .expires_at,
        u64::MAX
    );
    assert_eq!(recorder.len(), 1);
}

// HITL kernel-level flow tests.
//
// Included by `src/kernel/tests.rs`; the test module imports from the
// surrounding `kernel::tests` scope via `super::*`. Helpers such as
// `make_keypair` come from `tests/all.rs`.
//
// Scope: these tests exercise the HITL subsystem (approval store,
// approval guard, channels, replay protection, restart persistence)
// directly rather than through the full kernel evaluate path. Running
// the full pipeline would require standing up every downstream store
// (revocation, budget, authority, receipt log) for every case; a
// focused test against the primitives is faster and still covers every
// approval behaviour.

use std::sync::Arc as StdArc;

// Note: `GovernedApprovalDecision`, `GovernedApprovalToken`,
// `GovernedApprovalTokenBody`, and `Keypair` are already brought into
// scope by `tests/all.rs`. Only pull in HITL-specific items. These
// paths intentionally resolve through `crate::approval*` so the test
// exercises the same type identities that downstream consumers see.
use crate::approval::{
    compute_parameter_hash, resume_with_decision, ApprovalContext, ApprovalDecision, ApprovalGuard,
    ApprovalOutcome, ApprovalRequest, ApprovalStore, ApprovalToken, HitlVerdict,
    InMemoryApprovalStore,
};
use crate::approval_channels::RecordingChannel;
use crate::governed_active_response::{
    GovernedActiveResponseDispatchCommit, GovernedActiveResponseRequest,
};
use crate::threshold_approval::ThresholdApprovalRequirementResolver;
use chio_core::capability::governance::{
    GovernedResponseEffect, GovernedResponsePlanIntentBody, GovernedTransactionIntentBody,
    ThresholdApprovalProposal, ThresholdApprovalProposalBody, ACTIVE_RESPONSE_PLAN_TOOL_NAME,
    ACTIVE_RESPONSE_SERVER_ID, GOVERNED_RESPONSE_PLAN_SCHEMA, THRESHOLD_APPROVAL_PROPOSAL_SCHEMA,
};
use chio_core::capability::threshold_approval::{
    ThresholdApprovalRequirement, ThresholdApproverIdentity,
};
use chio_log_redact::redacted;

struct FixedThresholdRequirement(ThresholdApprovalRequirement);

impl ThresholdApprovalRequirementResolver for FixedThresholdRequirement {
    fn resolve_requirement(
        &self,
        policy_hash: &str,
        _server_id: &str,
        _tool_name: &str,
    ) -> Result<Option<ThresholdApprovalRequirement>, String> {
        Ok((policy_hash == self.0.policy_hash).then(|| self.0.clone()))
    }
}

