        governed["call_chain"]["sessionAnchorId"],
        serde_json::json!(parent_anchor.session_anchor_id.clone())
    );
    assert_eq!(
        governed["call_chain"]["evidenceSources"],
        serde_json::json!(["local_parent_receipt_linkage"])
    );
}

