    assert_eq!(usage.as_ref().map_or(0, |usage| usage.invocation_count), 0);
    let committed_cost = match usage.as_ref() {
        Some(usage) => usage.committed_cost_units()?,
        None => 0,
    };
    assert_eq!(committed_cost, 0);

    Ok(())
}

