    let decoded = RetainedToolAdmissionRequestV1::from_canonical_bytes(retained.canonical_bytes())?;
    assert_eq!(decoded.authority_profile(), &profile);
    decoded.validate_request_material(&request)?;
    for (pointer, value) in [
        (
            "/selection/runtime/runtime_authority_id",
            serde_json::json!("other-runtime"),
        ),
        (
            "/selection/runtime/expectation_id",
            serde_json::json!("other-runtime-generation"),
        ),
        (
            "/selection/approval/approval_authority_id",
            serde_json::json!("other-approval"),
        ),
        (
            "/selection/approval/expectation_id",
            serde_json::json!("other-approval-generation"),
        ),
        (
            "/selection/dpop/destination_store_uuid",
            serde_json::json!("22222222-2222-4222-8222-222222222222"),
        ),
        (
            "/selection/dpop/dpop_authority_id",
            serde_json::json!("other-dpop"),
        ),
        (
            "/selection/dpop/expectation_id",
            serde_json::json!("b".repeat(64)),
        ),
        ("/selection/dpop/proof_ttl_secs", serde_json::json!(61)),
        ("/selection/dpop/max_clock_skew_secs", serde_json::json!(31)),
        (
            "/selection/swarm_admission_required",
            serde_json::json!(true),
        ),
        (
            "/selection/runtime_enforces_swarm_authority",
            serde_json::json!(false),
        ),
        ("/selection/runtime", serde_json::Value::Null),
        ("/selection/approval", serde_json::Value::Null),
        ("/selection/dpop", serde_json::Value::Null),
    ] {
        let mut changed = wire.clone();
        *changed
            .pointer_mut(pointer)
            .ok_or("missing profile field")? = value;
        let profile: AdmissionAuthorityProfileV1 = serde_json::from_value(changed)?;
        assert_ne!(
            immutable_tool_request_hash_with_profile(
                &request,
                &matching,
                &[],
                None,
                Some(&profile)
            )?,
            actual,
            "{pointer}"
        );
    }
    Ok(())
}

#[test]
fn retained_current_profile_rejects_downgrades_duplicates_and_aliases(
) -> Result<(), Box<dyn std::error::Error>> {
    use crate::admission_operation::{
        AdmissionAuthorityProfileV1, AdmissionOperationStoreError, RetainedToolAdmissionRequestV1,
    };
    let (_, mut request, _, _) = durable_admission_fixture("retained-current-contract");
    request.arguments = serde_json::json!({"private_sentinel": {"count": 1}});
    let matching = resolve_required_matching_grants(
        &request.capability,
        &request.tool_name,
        &request.server_id,
        &request.arguments,
        request.model_metadata.as_ref(),
    )?;
    let retained = RetainedToolAdmissionRequestV1::from_admission(
        &request,
        &matching,
        &[],
        None,
        &AdmissionAuthorityProfileV1::unconfigured_for_test()?,
    )?;
    let bytes = retained.canonical_bytes();
    assert_eq!(
        RetainedToolAdmissionRequestV1::from_canonical_bytes(bytes)?.canonical_bytes(),
        bytes
    );
    let wire: serde_json::Value = serde_json::from_slice(bytes)?;
    for schema in [
        "chio.retained-tool-admission-request.v1",
        "chio.retained-tool-admission-request.v2",
        "chio.retained-tool-admission-request.v3",
    ] {
        let mut changed = wire.clone();
        changed["schema"] = schema.into();
        assert!(
            matches!(RetainedToolAdmissionRequestV1::from_canonical_bytes(&canonical_json_bytes(&changed)?),
            Err(AdmissionOperationStoreError::Invariant(message)) if message == "retained request contains unsupported authority material")
        );
    }
    let mut missing = wire.clone();
    missing
        .as_object_mut()
        .ok_or("object")?
        .remove("authority_profile");
    let error =
        RetainedToolAdmissionRequestV1::from_canonical_bytes(&canonical_json_bytes(&missing)?)
            .err()
            .ok_or("missing profile accepted")?;
    assert!(
        matches!(&error, AdmissionOperationStoreError::Operation(crate::admission_operation::AdmissionOperationError::UntrustedInput(cause))
        if cause.code() == "urn:chio:error:attest:signed-json-invalid-shape")
    );
    assert!(std::error::Error::source(&error).is_some());
    assert!(!format!("{error:?} {error}").contains("private_sentinel"));
    let text = std::str::from_utf8(bytes)?;
    for replacement in ["\"count\":1,\"count\":1", "\"count\":1e0"] {
        let changed = text.replace("\"count\":1", replacement);
        assert_ne!(changed.as_bytes(), bytes);
        assert!(
            matches!(RetainedToolAdmissionRequestV1::from_canonical_bytes(changed.as_bytes()),
            Err(AdmissionOperationStoreError::Operation(crate::admission_operation::AdmissionOperationError::UntrustedInput(cause))) if cause.code() == "urn:chio:error:attest:signed-json-noncanonical")
        );
    }
    Ok(())
}

//! A share snapshot samples physical time only after the mutation owner releases.

use super::*;
use crate::admission_operation::AdmissionMutationSequencer;
use std::sync::mpsc;
use std::time::Duration;

#[test]
fn caller_share_snapshot_waits_for_mutations_before_sampling_time(
) -> Result<(), Box<dyn std::error::Error>> {
    let (kernel, _, store, invocations) = durable_admission_fixture("snapshot-sequence");
    let fence = store
        .fence
        .lock()
        .map_err(|_| "fixture fence poisoned")?
        .clone();
    let sequencer = AdmissionMutationSequencer::for_fence(&fence)?;
    let held = sequencer.lock()?;
    let (started_tx, started_rx) = mpsc::channel();
    let (finished_tx, finished_rx) = mpsc::channel();
    std::thread::scope(|scope| -> Result<(), Box<dyn std::error::Error>> {
        let waiter = scope.spawn(|| {
            let _ = started_tx.send(());
            finished_tx
                .send(kernel.load_durable_caller_budget_shares("test-parent"))
                .is_ok()
        });
        started_rx.recv_timeout(Duration::from_secs(2))?;
        let premature = finished_rx.recv_timeout(Duration::from_millis(50));
        let released_at = current_unix_timestamp_ms();
        drop(held);
        let (early, result) = match premature {
            Ok(result) => (true, result),
            Err(mpsc::RecvTimeoutError::Timeout) => {
                (false, finished_rx.recv_timeout(Duration::from_secs(2))?)
            }
            Err(error) => return Err(error.into()),
        };
        assert!(waiter.join().map_err(|_| "snapshot worker panicked")?);
        assert!(
            !early,
            "share snapshot reached the store while a mutation was still owned"
        );
        assert!(
            result.is_err_and(|error| error.contains("sibling-share accounting is unsupported"))
        );
        let times = store
            .caller_share_times
            .lock()
            .map_err(|_| "fixture snapshot lock poisoned")?;
        assert_eq!(times.len(), 1);
        assert!(
            times[0] >= released_at,
            "snapshot retained its pre-lock timestamp"
        );
        assert_eq!(invocations.load(Ordering::SeqCst), 0);
        assert!(store
            .state
            .lock()
            .map_err(|_| "fixture state poisoned")?
            .operation
            .is_none());
        Ok(())
    })
}

use super::*;
use std::future::Future;
use std::pin::Pin;
use std::sync::Arc;
use std::task::{Context, Waker};

type TestResult = Result<(), Box<dyn std::error::Error>>;

#[derive(Clone, Copy)]
enum OwnedOutcome {
    Complete,
    CancelPreparation,
    CancelDispatch,
    Revoke,
    WrongServer,
}

struct OwnedFactory {
    outcome: OwnedOutcome,
    live: Arc<AtomicU64>,
    calls: Arc<AtomicU64>,
    revocations: Arc<crate::InMemoryRevocationStore>,
    capability: String,
}

struct OwnedConnection {
    outcome: OwnedOutcome,
    live: Arc<AtomicU64>,
    calls: Arc<AtomicU64>,
}

impl Drop for OwnedConnection {
    fn drop(&mut self) {
        self.live.fetch_sub(1, Ordering::SeqCst);
    }
}

#[async_trait::async_trait]
impl ToolServerConnection for OwnedFactory {
    fn server_id(&self) -> &str {
        "durable-server"
    }
    fn tool_names(&self) -> Vec<String> {
        vec!["mutate".into()]
    }
    async fn invoke(
        &self,
        _: &str,
        _: serde_json::Value,
        _: Option<&mut dyn NestedFlowBridge>,
    ) -> Result<serde_json::Value, KernelError> {
        Err(KernelError::ToolServerError(
            "factory must never dispatch".into(),
        ))
    }
    async fn prepare_invocation_connection(
        &self,
        _: &ToolDispatchContext,
    ) -> Result<Option<Arc<dyn ToolServerConnection>>, KernelError> {
        self.live.fetch_add(1, Ordering::SeqCst);
        let child = Arc::new(OwnedConnection {
            outcome: self.outcome,
            live: self.live.clone(),
            calls: self.calls.clone(),
        });
        match self.outcome {
            OwnedOutcome::CancelPreparation => std::future::pending::<()>().await,
            OwnedOutcome::Revoke => {
                self.revocations
                    .revoke(&self.capability)
                    .map_err(|error| KernelError::Internal(error.to_string()))?;
            }
            _ => {}
        }
        Ok(Some(child))
    }
}

#[async_trait::async_trait]
impl ToolServerConnection for OwnedConnection {
    fn server_id(&self) -> &str {
        if matches!(self.outcome, OwnedOutcome::WrongServer) {
            "substituted"
        } else {
            "durable-server"
        }
    }
    fn tool_names(&self) -> Vec<String> {
        vec!["mutate".into()]
    }
    async fn invoke(
        &self,
        _: &str,
        _: serde_json::Value,
        _: Option<&mut dyn NestedFlowBridge>,
    ) -> Result<serde_json::Value, KernelError> {
        self.calls.fetch_add(1, Ordering::SeqCst);
        if matches!(self.outcome, OwnedOutcome::CancelDispatch) {
            std::future::pending::<()>().await;
        }
        Ok(serde_json::json!({"owned": true}))
    }
}

#[test]
fn invocation_owned_connections_close_on_completion_denial_and_cancellation() -> TestResult {
    for nested in [false, true] {
        for outcome in [
            OwnedOutcome::Complete,
            OwnedOutcome::CancelPreparation,
            OwnedOutcome::CancelDispatch,
            OwnedOutcome::Revoke,
            OwnedOutcome::WrongServer,
        ] {
            let (mut kernel, request, store, calls) = durable_admission_fixture("owned-delivery");
            let live = Arc::new(AtomicU64::new(0));
            let revocations = Arc::new(crate::InMemoryRevocationStore::new());
            kernel.set_revocation_store_handle(revocations.clone());
            kernel.register_tool_server(Box::new(OwnedFactory {
                outcome,
                live: live.clone(),
                calls: calls.clone(),
                revocations,
                capability: request.capability.id.clone(),
            }));
            let session = kernel.open_session("owned-parent".into(), Vec::new())?;
            kernel.activate_session(&session)?;
            let parent = make_operation_context(&session, "owned-parent-request", "owned-parent");
            kernel.begin_session_request(&parent, OperationKind::ToolCall, true)?;
            let mut client = NoopNestedFlowClient;
            let mut evaluation: Pin<
                Box<dyn Future<Output = Result<ToolCallResponse, KernelError>> + '_>,
            > = if nested {
                Box::pin(kernel.evaluate_tool_call_with_nested_flow_client_async(
                    &parent,
                    &request,
                    &mut client,
                    None,
                ))
            } else {
                Box::pin(kernel.evaluate_tool_call(&request))
            };
            if matches!(
                outcome,
                OwnedOutcome::CancelPreparation | OwnedOutcome::CancelDispatch
            ) {
                assert!(evaluation
                    .as_mut()
                    .poll(&mut Context::from_waker(Waker::noop()))
                    .is_pending());
                assert_eq!(live.load(Ordering::SeqCst), 1);
                drop(evaluation);
                assert_eq!(
                    store.operation().state(),
                    if matches!(outcome, OwnedOutcome::CancelDispatch) {
                        AdmissionOperationState::OutcomeUnknownAfterDispatch
                    } else {
                        AdmissionOperationState::CompensatedBeforeDispatch
                    }
                );
            } else {
                let response = block_on_async_tool_dispatch(evaluation)?;
                assert_eq!(
                    response.verdict,
                    if matches!(outcome, OwnedOutcome::Complete) {
                        Verdict::Allow
                    } else {
                        Verdict::Deny
                    },
                    "{response:?}"
                );
            }
            assert_eq!(
                live.load(Ordering::SeqCst),
                0,
                "invocation retained its connection after termination"
            );
            assert_eq!(
                calls.load(Ordering::SeqCst),
                u64::from(matches!(
                    outcome,
                    OwnedOutcome::Complete | OwnedOutcome::CancelDispatch
                ))
            );
        }
    }
    Ok(())
}

enum PreparationMutation {
    None,
    Revoke(Arc<crate::InMemoryRevocationStore>, String),
    Reject,
    InvalidateAdmission(Arc<AtomicBool>),
}

struct PreparingServer {
    mutation: PreparationMutation,
    yield_once: bool,
    preparations: Arc<AtomicU64>,
    invocations: Arc<AtomicU64>,
}

#[async_trait::async_trait]
impl ToolServerConnection for PreparingServer {
    fn server_id(&self) -> &str {
        "durable-server"
    }

    fn tool_names(&self) -> Vec<String> {
        vec!["mutate".to_owned()]
    }

    async fn prepare_delivery(&self, _: &ToolDispatchContext) -> Result<(), KernelError> {
        self.preparations.fetch_add(1, Ordering::SeqCst);
        let mut yielded = !self.yield_once;
        std::future::poll_fn(|cx| {
            if yielded {
                std::task::Poll::Ready(())
            } else {
                yielded = true;
                cx.waker().wake_by_ref();
                std::task::Poll::Pending
            }
        })
        .await;
        match &self.mutation {
            PreparationMutation::None => {}
            PreparationMutation::Revoke(store, capability) => {
                store
                    .revoke(capability)
                    .map_err(|error| KernelError::Internal(error.to_string()))?;
            }
            PreparationMutation::Reject => {
                return Err(KernelError::ToolServerError(
                    "injected unreachable server".to_owned(),
                ));
            }
            PreparationMutation::InvalidateAdmission(live) => live.store(false, Ordering::SeqCst),
        }
        Ok(())
    }

    async fn invoke(
        &self,
        _: &str,
        _: serde_json::Value,
        _: Option<&mut dyn NestedFlowBridge>,
    ) -> Result<serde_json::Value, KernelError> {
        self.invocations.fetch_add(1, Ordering::SeqCst);
        Ok(serde_json::json!({"mutated": true}))
    }
}

fn assert_delivery_revocation_denied(nested: bool) -> TestResult {
    let (mut kernel, request, store, invocations) =
        durable_admission_fixture("revoke-during-delivery-preparation");
    let revocations = Arc::new(crate::InMemoryRevocationStore::new());
    kernel.set_revocation_store_handle(revocations.clone());
    let preparations = Arc::new(AtomicU64::new(0));
    kernel.register_tool_server(Box::new(PreparingServer {
        mutation: PreparationMutation::Revoke(revocations, request.capability.id.clone()),
        yield_once: true,
        preparations: preparations.clone(),
        invocations: invocations.clone(),
    }));
    let response = if nested {
        let session_id = kernel.open_session("delivery-parent".to_owned(), Vec::new())?;
        kernel.activate_session(&session_id)?;
        let parent =
            make_operation_context(&session_id, "delivery-parent-request", "delivery-parent");
        kernel.begin_session_request(&parent, OperationKind::ToolCall, true)?;
        kernel.evaluate_tool_call_with_nested_flow_client(
            &parent,
            &request,
            &mut NoopNestedFlowClient,
            None,
        )?
    } else {
        kernel.evaluate_tool_call_blocking(&request)?
    };
    assert_eq!(preparations.load(Ordering::SeqCst), 1);
    assert_eq!(
        invocations.load(Ordering::SeqCst),
        0,
        "revoked capability reached the tool"
    );
    assert_eq!(response.verdict, Verdict::Deny, "{response:?}");
    assert!(response.receipt.verify_signature()?);
    assert_eq!(
        store.operation().state(),
        AdmissionOperationState::CompensatedBeforeDispatch
    );
    Ok(())
}

#[test]
fn remote_delivery_rechecks_revocation_after_preparation() -> TestResult {
    assert_delivery_revocation_denied(false)
}

#[test]
fn nested_remote_delivery_rechecks_revocation_after_preparation() -> TestResult {
    assert_delivery_revocation_denied(true)
