            now
        )
        .is_err());
    // Historical verification does not extend live execution permission.
    assert!(evidence
        .reverify(
            &fixture.request,
            ["kernel.org-a", "kernel.org-b"],
            [&origin, &local],
            4_102_444_800_000
        )
        .is_err());
    Ok(())
}

