#[test]
fn concurrent_recovery_keeps_distinct_treaty_reports_for_the_same_request_id() -> TestResult {
    let local = Keypair::generate();
    let origin = Keypair::generate();
    let overlap = Arc::new(RecoveryOverlap::default());
    let probes = [0, 1].map(|_| {
        Arc::new(RecoveryProbe {
            kernel: Mutex::new(Weak::new()),
            overlap: overlap.clone(),
            reports: Mutex::new(Vec::new()),
        })
    });
    let reports = ["a".repeat(64), "b".repeat(64)];
    let fixtures = [
        pending_fixture(&local, &origin, &reports[0], &probes[0])?,
        pending_fixture(&local, &origin, &reports[1], &probes[1])?,
    ];
    assert_eq!(
        fixtures[0].request.request_id,
        fixtures[1].request.request_id
    );
    assert_ne!(
        fixtures[0].request.capability.id,
        fixtures[1].request.capability.id
    );
    assert_ne!(
        fixtures[0].store.operation().binding().operation_id(),
        fixtures[1].store.operation().binding().operation_id()
    );
    let first = restart(&fixtures[0], &probes[0])?;
    let mut second = restart(&fixtures[1], &probes[1])?;
    // The existing fixture store holds one operation. Share the production map
    // to exercise the same collision as two sweeps on a single kernel, while
    // retaining independent real admission and outcome records for both rows.
    second.receipt_federation_admissions = first.receipt_federation_admissions.clone();
    let kernels = [Arc::new(first), Arc::new(second)];
    for (probe, kernel) in probes.iter().zip(&kernels) {
        *probe.kernel.lock().map_err(|_| "probe lock")? = Arc::downgrade(kernel);
    }
    let results = std::thread::scope(|threads| {
        let first = threads.spawn(|| kernels[0].reconcile_recoverable_admissions());
        let second = threads.spawn(|| kernels[1].reconcile_recoverable_admissions());
        [first.join(), second.join()]
    });
    for (index, result) in results.into_iter().enumerate() {
        assert_eq!(result.map_err(|_| "recovery worker panicked")??, 1);
        assert_eq!(
            *probes[index].reports.lock().map_err(|_| "report lock")?,
            vec![reports[index].clone()]
        );
        assert_eq!(fixtures[index].invocations.load(Ordering::SeqCst), 1);
        assert_eq!(
            fixtures[index].store.operation().state(),
            AdmissionOperationState::Completed
        );
        let state = fixtures[index]
            .store
            .state
            .lock()
            .map_err(|_| "state lock")?;
        let receipt = state.receipt.as_ref().ok_or("terminal receipt")?;
        let envelope = kernels[index]
            .federation_dsse_envelope(&receipt.id)
            .ok_or("bilateral DSSE")?;
        let statement = chio_federation::bilateral_dsse::verify_chio_bilateral_dsse_envelope(
            &envelope,
            &origin.public_key(),
            &local.public_key(),
        )?;
        assert_eq!(
            statement
                .predicate
                .treaty_binding_ref
                .ok_or("treaty binding")?
                .admission_report_sha256,
            reports[index]
        );
        assert!(receipt.verify_signature()?);
    }
    assert!(kernels[0].receipt_federation_admissions.is_empty());
    assert!(current_receipt_evaluation_scope_key().is_none());
    Ok(())
}

//! Adversarial coordinator callbacks, not SQLite source or commit qualification.
use super::*;
use crate::admission_operation::governed_approval_claim::*;
use crate::admission_operation::governed_approval_replay::*;
use crate::admission_operation::{AdmissionDigest, AdmissionRecoveryLease};
use std::sync::{Arc, Mutex};

#[derive(Clone, Copy, Default, Debug)]
enum Mode {
    #[default]
    Normal,
    NoOp,
    LostAck,
    Panic,
    WrongReference,
    WrongSuccessor,
    HistoryPanic,
}

#[derive(Default)]
pub(super) struct TestApproval(Mutex<State>);
#[derive(Default)]
struct State {
    source: Option<GovernedApprovalReplaySourceSnapshot>,
    history: Vec<GovernedApprovalClaimHistoryV1>,
    mode: Mode,
    history_panics: usize,
    release_noop: bool,
}

impl TestApproval {
    pub(super) fn activation(
        &self,
        binding: &GovernedApprovalAuthorityBindingV1,
    ) -> Result<GovernedApprovalReplaySourceSnapshot, AdmissionOperationStoreError> {
        let state = self.0.lock().expect("approval state");
        let source = state.source.as_ref().ok_or_else(|| {
            AdmissionOperationStoreError::Unavailable("test approval source unsupported".into())
        })?;
        if binding.approval_authority_id().as_str() != source.approval_authority_id() {
            return Err(AdmissionOperationStoreError::Fenced);
        }
        Ok(source.clone())
    }

    pub(super) fn claim(
        &self,
        store: &TestAdmissionOperationStore,
        original: &AdmissionOperationV1,
        lease: &AdmissionRecoveryLease,
        intent: &GovernedApprovalClaimIntentV1,
        now: u64,
    ) -> Result<
        (AdmissionOperationV1, GovernedApprovalClaimReferenceV1),
        AdmissionOperationStoreError,
    > {
        let mode = self.0.lock().expect("state").mode;
        let reference = GovernedApprovalClaimReferenceV1::new(
            original.binding().operation_id().clone(),
            intent.episode_id().clone(),
            digest('c'),
        );
        if matches!(mode, Mode::NoOp) {
            return Ok((original.clone(), reference));
        }
        let command = AdmissionOperationCommand::new(
            original.binding().operation_id().clone(),
            original.version(),
            lease.clone(),
            vec![AdmissionAttachment::GovernedApprovalLedgerDigest(digest(
                'a',
            ))],
            Some(original.state()),
            None,
            None,
        )?;
        let updated = original.apply_command(&command, now)?.into_operation();
        store.state.lock().expect("operation").operation = Some(updated.clone());
        {
            let mut state = self.0.lock().expect("state");
            state.history.push(GovernedApprovalClaimHistoryV1 {
                reference: reference.clone(),
                intent: intent.clone(),
                disposition: GovernedApprovalClaimDisposition::ReservedBeforeDispatch,
            });
            if matches!(mode, Mode::HistoryPanic) {
                state.history_panics = 1;
            }
        }
        match mode {
            Mode::LostAck => Err(AdmissionOperationStoreError::OutcomeUnknown(
                "lost approval claim acknowledgement".into(),
            )),
            Mode::Panic => panic!("approval committed then callback panicked"),
            Mode::WrongReference => Ok((
                updated,
                GovernedApprovalClaimReferenceV1::new(
                    reference.operation_id().clone(),
                    reference.episode_id().clone(),
                    digest('f'),
                ),
            )),
            Mode::WrongSuccessor => Ok((original.clone(), reference)),
            _ => Ok((updated, reference)),
        }
    }

    pub(super) fn history(
        &self,
        operation: Option<AdmissionOperationV1>,
    ) -> Result<
        Option<(AdmissionOperationV1, Vec<GovernedApprovalClaimHistoryV1>)>,
        AdmissionOperationStoreError,
    > {
        let mut state = self.0.lock().expect("state");
        if state.history_panics > 0 {
            state.history_panics -= 1;
            drop(state);
            panic!("approval history readback panicked");
        }
        Ok(operation.map(|operation| (operation, state.history.clone())))
    }

    pub(super) fn release(
        &self,
        reference: &GovernedApprovalClaimReferenceV1,
    ) -> Result<(), AdmissionOperationStoreError> {
        let mut state = self.0.lock().expect("state");
        if state.release_noop {
            return Ok(());
        }
        let claim = state
            .history
            .iter_mut()
            .find(|claim| &claim.reference == reference)
            .ok_or(AdmissionOperationStoreError::NotFound)?;
        claim.disposition = GovernedApprovalClaimDisposition::ReleasedBeforeDispatch;
        Ok(())
    }
}

