    fn begin_with_retained_tool_request(
        &self,
        operation: &AdmissionOperationV1,
        request: &crate::admission_operation::RetainedToolAdmissionRequestV1,
        fence: &StoreMutationFence,
        _trusted_now_unix_ms: u64,
    ) -> Result<AdmissionBeginResult, AdmissionOperationStoreError> {
        self.begin_retained_request(operation, request, fence)
    }

    fn load_retained_tool_request(
        &self,
        operation_id: &AdmissionOperationId,
        fence: &StoreMutationFence,
        _: u64,
    ) -> Result<
        Option<(
            AdmissionOperationV1,
            crate::admission_operation::RetainedToolAdmissionRequestV1,
        )>,
        AdmissionOperationStoreError,
    > {
        self.require_fence(fence)?;
        let state = self.state.lock().expect("test admission state");
        let Some(operation) = state
            .operation
            .as_ref()
            .filter(|operation| operation.binding().operation_id() == operation_id)
        else {
            return Ok(None);
        };
        Ok(state
            .retained_request
            .as_ref()
            .map(|request| (operation.clone(), request.clone())))
    }

    fn begin(
        &self,
        operation: &AdmissionOperationV1,
        fence: &StoreMutationFence,
        _trusted_now_unix_ms: u64,
    ) -> Result<AdmissionBeginResult, AdmissionOperationStoreError> {
        self.require_fence(fence)?;
        operation.validate()?;
        let mut state = self.state.lock().expect("test admission state lock");
        let Some(existing) = state.operation.as_ref() else {
            state.operation = Some(operation.clone());
            return Ok(AdmissionBeginResult::Created(operation.clone()));
        };
        Ok(match existing.classify_replay(operation) {
            AdmissionReplayClassification::Exact { terminal_replay } => {
                AdmissionBeginResult::ExactReplay {
                    operation: existing.clone(),
                    terminal_replay,
                }
            }
            AdmissionReplayClassification::Conflict => AdmissionBeginResult::Conflict {
                existing_operation_id: existing.binding().operation_id().clone(),
            },
        })
    }

    fn load_by_operation_id(
        &self,
        operation_id: &AdmissionOperationId,
    ) -> Result<Option<AdmissionOperationV1>, AdmissionOperationStoreError> {
        self.recovery_lease_faults
            .trip(recovery_lease::Stage::OperationRead);
        Ok(self
            .state
            .lock()
            .expect("test admission state lock")
            .operation
            .as_ref()
            .filter(|operation| operation.binding().operation_id() == operation_id)
            .cloned())
    }

    fn load_by_replay_key(
        &self,
        replay_key: &AdmissionReplayKey,
    ) -> Result<Option<AdmissionOperationV1>, AdmissionOperationStoreError> {
        Ok(self
            .state
            .lock()
            .expect("test admission state lock")
            .operation
            .as_ref()
            .filter(|operation| &operation.replay_key() == replay_key)
            .cloned())
    }

    fn compare_and_swap(
        &self,
        command: &AdmissionOperationCommand,
        trusted_now_unix_ms: u64,
    ) -> Result<AdmissionCommandResult, AdmissionOperationStoreError> {
        let mut state = self.state.lock().expect("test admission state lock");
        let operation = state
            .operation
            .as_ref()
            .filter(|operation| operation.binding().operation_id() == command.operation_id())
            .cloned()
            .ok_or(AdmissionOperationStoreError::NotFound)?;
        let claim = state
            .claim
            .as_ref()
            .filter(|claim| claim.operation_id() == command.operation_id())
            .ok_or(AdmissionOperationStoreError::Fenced)?;
        let lease = command.recovery_lease();
        if claim.claimant_id() != lease.claimant_id()
            || claim.coordinator_lease_id() != lease.coordinator_lease_id()
            || claim.claimed_version() != lease.claimed_version()
            || claim.expires_at_unix_ms() != lease.expires_at_unix_ms()
            || claim.store_fence() != lease.store_fence()
        {
            return Err(AdmissionOperationStoreError::Fenced);
        }
        let result = operation.apply_command(command, trusted_now_unix_ms)?;
        state.operation = Some(result.clone().into_operation());
        state.claim = None;
        Ok(result)
    }

    fn claim_recovery_untrusted(
        &self,
        operation_id: &AdmissionOperationId,
        expected_version: u64,
        claimant_id: &AdmissionIdentifier,
        _trusted_now_unix_ms: u64,
        expires_at_unix_ms: u64,
        fence: &StoreMutationFence,
    ) -> Result<UntrustedAdmissionRecoveryClaim, AdmissionOperationStoreError> {
        self.recovery_lease_faults
            .trip(recovery_lease::Stage::ClaimBefore);
        self.require_fence(fence)?;
        let mut state = self.state.lock().expect("test admission state lock");
        let operation = state
            .operation
            .as_ref()
            .filter(|operation| operation.binding().operation_id() == operation_id)
            .ok_or(AdmissionOperationStoreError::NotFound)?;
        if operation.version() != expected_version {
            return Err(AdmissionOperationError::StaleVersion {
                expected: expected_version,
                actual: operation.version(),
            }
            .into());
        }
        let claim = UntrustedAdmissionRecoveryClaim::new(
            operation_id.clone(),
            claimant_id.clone(),
            AdmissionIdentifier::try_new("coordinator_lease_id", fence.lease_id.clone())?,
            operation.coordinator_lease_epoch(),
            expected_version,
            expires_at_unix_ms,
            fence.clone(),
        )?;
        state.claim = Some(claim.clone());
        drop(state);
        self.recovery_lease_faults
            .trip(recovery_lease::Stage::ClaimAfter);
        Ok(claim)
    }

    fn revalidate_recovery_claim(
        &self,
        operation: &AdmissionOperationV1,
        claim: &UntrustedAdmissionRecoveryClaim,
        trusted_now_unix_ms: u64,
        current_store_fence: &StoreMutationFence,
    ) -> Result<(), AdmissionOperationStoreError> {
        self.recovery_lease_faults
            .trip(recovery_lease::Stage::Revalidate);
        self.require_fence(current_store_fence)?;
        let state = self.state.lock().expect("test admission state lock");
        if state.operation.as_ref() != Some(operation)
            || state.claim.as_ref() != Some(claim)
            || trusted_now_unix_ms >= claim.expires_at_unix_ms()
        {
            return Err(AdmissionOperationStoreError::Fenced);
        }
        Ok(())
    }

    fn list_recoverable(
        &self,
        not_after_unix_ms: u64,
        limit: usize,
    ) -> Result<Vec<AdmissionOperationV1>, AdmissionOperationStoreError> {
        let store_fence = self
            .fence
            .lock()
            .expect("test admission fence lock")
            .clone();
        let state = self.state.lock().expect("test admission state lock");
        // Mirror the durable store's recovery contract: an operation still under a
        // live recovery lease held by the serving fence is being actively driven
        // and is not recoverable. Only an expired lease, a lease from another
        // fence, or no lease at all makes an operation eligible for the sweep.
        Ok(state
            .operation
            .iter()
            .filter(|operation| !operation.state().is_terminal())
            .filter(|operation| {
                operation
                    .parked_approval_deadline_unix_ms()
                    .expect("parked operation retains its proposal")
                    .is_none_or(|deadline| deadline <= not_after_unix_ms)
            })
            .filter(|operation| {
                !state.claim.as_ref().is_some_and(|claim| {
                    claim.operation_id() == operation.binding().operation_id()
                        && claim.expires_at_unix_ms() > not_after_unix_ms
                        && claim.store_fence() == &store_fence
                })
            })
            .take(limit)
            .cloned()
            .collect())
    }

    fn load_terminal_replay(
        &self,
        replay_key: &AdmissionReplayKey,
    ) -> Result<Option<AdmissionTerminalReplay>, AdmissionOperationStoreError> {
        Ok(self
            .load_by_replay_key(replay_key)?
            .and_then(|operation| operation.terminal_replay().cloned()))
    }
}

impl QualifiedAdmissionOperationStore for TestAdmissionOperationStore {}

use super::*;

#[derive(Clone, Default)]
pub(super) struct AdmissionReceiptProjectionStore {
    receipts: std::sync::Arc<std::sync::Mutex<std::collections::BTreeMap<String, ChioReceipt>>>,
    successful_appends: std::sync::Arc<AtomicU64>,
    fail_next_append: std::sync::Arc<AtomicBool>,
    batch_lookups: std::sync::Arc<AtomicU64>,
    point_lookups: std::sync::Arc<AtomicU64>,
}

impl AdmissionReceiptProjectionStore {
    pub(super) fn fail_next_append(&self) {
        self.fail_next_append.store(true, Ordering::SeqCst);
    }

    pub(super) fn receipt(&self) -> Option<ChioReceipt> {
        self.receipts
            .lock()
            .expect("admission receipt projection lock")
            .values()
            .next()
            .cloned()
    }

    pub(super) fn successful_appends(&self) -> u64 {
        self.successful_appends.load(Ordering::SeqCst)
    }
}

impl ReceiptStore for AdmissionReceiptProjectionStore {
    fn append_chio_receipt(&self, receipt: &ChioReceipt) -> Result<(), ReceiptStoreError> {
        if self.fail_next_append.swap(false, Ordering::SeqCst) {
            return Err(ReceiptStoreError::Conflict(
                "injected admission receipt projection failure".to_owned(),
            ));
        }
        let mut stored = self.receipts.lock().map_err(|_| {
            ReceiptStoreError::Conflict("admission receipt projection lock poisoned".to_owned())
        })?;
        if let Some(existing) = stored.get(&receipt.id) {
            let existing = chio_core::canonical::canonical_json_bytes(existing)
                .map_err(|error| ReceiptStoreError::Canonical(error.to_string()))?;
            let projected = chio_core::canonical::canonical_json_bytes(receipt)
                .map_err(|error| ReceiptStoreError::Canonical(error.to_string()))?;
            return (existing == projected).then_some(()).ok_or_else(|| {
                ReceiptStoreError::Conflict("admission receipt projection id conflicts".to_owned())
            });
        }
        stored.insert(receipt.id.clone(), receipt.clone());
        self.successful_appends.fetch_add(1, Ordering::SeqCst);
        Ok(())
    }

    fn durable_sink_id(&self) -> Option<&str> {
        Some("receipt-sink:admission-projection-test")
    }

    fn load_chio_receipt(
        &self,
        receipt_id: &str,
    ) -> Result<Option<ChioReceipt>, ReceiptStoreError> {
        self.point_lookups.fetch_add(1, Ordering::SeqCst);
        Ok(self
            .receipts
            .lock()
            .map_err(|_| {
                ReceiptStoreError::Conflict("admission receipt projection lock poisoned".to_owned())
            })?
            .get(receipt_id)
            .cloned())
    }

    fn load_chio_receipts(
        &self,
        receipt_ids: &[&str],
    ) -> Result<Vec<Option<ChioReceipt>>, ReceiptStoreError> {
        self.batch_lookups.fetch_add(1, Ordering::SeqCst);
        let stored = self.receipts.lock().map_err(|_| {
            ReceiptStoreError::Conflict("admission receipt projection lock poisoned".to_owned())
        })?;
        Ok(receipt_ids
            .iter()
            .map(|id| stored.get(*id).cloned())
            .collect())
    }

    fn append_child_receipt(
        &self,
        _receipt: &chio_core::receipt::lineage::ChildRequestReceipt,
    ) -> Result<(), ReceiptStoreError> {
        Err(ReceiptStoreError::Unsupported(
            "test child receipt persistence".to_owned(),
        ))
    }
}

#[test]
fn existing_admission_projections_use_verified_batch_without_point_reads_or_appends() {
    let (mut kernel, request, _store, invocations) =
        durable_admission_fixture("durable-batch-existing-projection");
    let completed = kernel
        .evaluate_tool_call_blocking(&request)
        .expect("complete tool call");
    let projection = AdmissionReceiptProjectionStore::default();
    projection
        .append_chio_receipt(&completed.receipt)
        .expect("seed existing projection");
    kernel
        .set_receipt_store(Box::new(projection.clone()))
        .expect("install projection store");
    assert_eq!(
        kernel
            .reconcile_durable_admission_receipt_projections()
            .expect("reconcile existing"),
        1
    );
    assert_eq!(projection.batch_lookups.load(Ordering::SeqCst), 1);
    assert_eq!(projection.point_lookups.load(Ordering::SeqCst), 0);
    assert_eq!(projection.successful_appends(), 1);
    assert_eq!(invocations.load(Ordering::SeqCst), 1);

    projection
        .receipts
        .lock()
        .expect("projection lock")
        .get_mut(&completed.receipt.id)
        .expect("projected receipt")
        .tool_name = "forged".to_owned();
    let error = kernel
        .reconcile_durable_admission_receipt_projections()
        .expect_err("reject changed projection");
    assert!(error
        .to_string()
        .contains("conflicts with the canonical admission receipt"));
    assert_eq!(invocations.load(Ordering::SeqCst), 1);
}

//! Qualified-port fault contracts, not physical backend qualification. Panics
//! occur outside fixture locks so poisoning of the caller's lock is observable.
use super::*;
use crate::admission_operation::QualifiedAdmissionOperationStoreExt;
use std::panic::{catch_unwind, AssertUnwindSafe};
use std::sync::{atomic::AtomicU8, Mutex};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
#[repr(u8)]
pub(super) enum Stage {
    ClaimBefore = 1,
    ClaimAfter = 2,
    OperationRead = 3,
    Revalidate = 4,
}

#[derive(Default)]
pub(super) struct TestRecoveryLeaseFaults(AtomicU8);

impl TestRecoveryLeaseFaults {
    pub(super) fn arm(&self, stage: Stage) {
        assert_eq!(self.0.swap(stage as u8, Ordering::SeqCst), 0);
    }

    pub(super) fn trip(&self, stage: Stage) {
        let triggered = self
            .0
            .compare_exchange(stage as u8, 0, Ordering::SeqCst, Ordering::SeqCst)
            .is_ok();
        assert!(!triggered, "test recovery qualification panic at {stage:?}");
    }
}

fn exercise_panic(stage: Stage) -> Result<(), Box<dyn std::error::Error>> {
    let (kernel, request, store, invocations) = durable_admission_fixture("lease-qualification");
    let now = current_unix_timestamp_ms();
    let admission = kernel
        .begin_durable_tool_admission(&request, &security_binding::matching(&request)?, now)?
        .ok_or("durable admission")?;
    let original = admission.operation();
    let fence = store.fence.lock().expect("fence").clone();
    let claimant = AdmissionIdentifier::try_new("claimant", "test-qualification")?;
    let expires = now + 60_000;
    let sequencer = Mutex::new(());
    assert!(store.state.lock().expect("state").claim.is_none());
    store.recovery_lease_faults.arm(stage);
    let outcome = catch_unwind(AssertUnwindSafe(|| {
        let _guard = sequencer.lock().expect("caller sequencer");
        store.claim_recovery(
            original.binding().operation_id(),
            original.version(),
            &claimant,
            now,
            expires,
            &fence,
        )
    }));
    assert!(
        outcome.is_ok(),
        "{stage:?}: store panic escaped qualification"
    );
    assert!(
        matches!(
            outcome.expect("contained panic"),
            Err(AdmissionOperationStoreError::OutcomeUnknown(_))
        ),
        "a panicking callback cannot mint a lease or assert rollback"
    );
    let _guard = sequencer.lock().expect("caller sequencer remains usable");
    assert_eq!(store.operation(), *original);
    {
        let state = store.state.lock().expect("state");
        assert_eq!(state.claim.is_some(), stage != Stage::ClaimBefore);
        if let Some(claim) = &state.claim {
            assert_eq!(claim.operation_id(), original.binding().operation_id());
            assert_eq!(claim.claimant_id(), &claimant);
            assert_eq!(claim.claimed_version(), original.version());
            assert_eq!(claim.expires_at_unix_ms(), expires);
            assert_eq!(claim.store_fence(), &fence);
        }
    }
    // Fresh qualification against a healthy backend must still execute every
    // check. The previous unknown outcome itself conveys no reusable authority.
    let lease = store.claim_recovery(
        original.binding().operation_id(),
        original.version(),
        &claimant,
        now,
        expires,
        &fence,
    )?;
    assert_eq!(
        lease.untrusted_claim(),
        store
            .state
            .lock()
            .expect("state")
            .claim
            .as_ref()
            .expect("claim")
    );
    assert_eq!(store.operation(), *original);
    assert_eq!(invocations.load(Ordering::SeqCst), 0);
    Ok(())
}

#[test]
fn qualification_contains_claim_panic_before_persistence() -> Result<(), Box<dyn std::error::Error>>
{
    exercise_panic(Stage::ClaimBefore)
}

#[test]
fn qualification_contains_claim_panic_after_persistence() -> Result<(), Box<dyn std::error::Error>>
{
    exercise_panic(Stage::ClaimAfter)
}

#[test]
fn qualification_contains_operation_read_panic() -> Result<(), Box<dyn std::error::Error>> {
    exercise_panic(Stage::OperationRead)
}

#[test]
fn qualification_contains_revalidation_panic() -> Result<(), Box<dyn std::error::Error>> {
    exercise_panic(Stage::Revalidate)
}

#[test]
fn qualification_preserves_ordinary_errors_without_creating_claims(
) -> Result<(), Box<dyn std::error::Error>> {
    let (kernel, request, store, invocations) = durable_admission_fixture("lease-errors");
    let now = current_unix_timestamp_ms();
    let admission = kernel
        .begin_durable_tool_admission(&request, &security_binding::matching(&request)?, now)?
        .ok_or("durable admission")?;
    let original = admission.operation();
    let fence = store.fence.lock().expect("fence").clone();
    let claimant = AdmissionIdentifier::try_new("claimant", "test-qualification")?;
    let stale_version = original.version() + 1;
    assert_eq!(
        store.claim_recovery(
            original.binding().operation_id(),
            stale_version,
            &claimant,
            now,
            now + 60_000,
            &fence
        ),
        Err(AdmissionOperationStoreError::Operation(
            AdmissionOperationError::StaleVersion {
                expected: stale_version,
                actual: original.version(),
            }
        ))
    );
    let mut stale_fence = fence.clone();
    stale_fence.owner_epoch += 1;
    assert_eq!(
        store.claim_recovery(
            original.binding().operation_id(),
            original.version(),
            &claimant,
            now,
            now + 60_000,
            &stale_fence
        ),
        Err(AdmissionOperationStoreError::Fenced)
    );
    assert!(store.state.lock().expect("state").claim.is_none());
    assert_eq!(store.operation(), *original);
    assert_eq!(invocations.load(Ordering::SeqCst), 0);
    Ok(())
}

