        Ok(GuardDecision::allow())
    }
}

struct OptInFailingGuard;

impl Guard for OptInFailingGuard {
    fn name(&self) -> &str {
        "opt-in-failing-guard"
    }

    fn evaluate(&self, _ctx: &GuardContext<'_>) -> Result<GuardDecision, KernelError> {
