            tool_name: "read_file",
            server_id: "srv-a",
            decision: Decision::Allow,
            action: ToolCallAction::from_parameters(serde_json::json!({
                "path": "/app/src/main.rs",
            }))
            .unwrap(),
            content_hash: content_hash.clone(),
