    fn verify_shared_with_resolver(
        &self,
        algorithms: &[SigningAlgorithm],
        resolver: &dyn ThresholdApprovalRequirementResolver,
    ) -> TestResult<crate::threshold_approval::VerifiedThresholdApprovalSet> {
        let proposal = self
            .request
